function Preserve-ProVolumeFailure($Session,[string]$CaseId,[bool]$Finish=$false){
 return Invoke-Command -Session $Session -ArgumentList $CaseId,$Finish -ScriptBlock {
  param($caseId,$finish)
  $ErrorActionPreference='Stop';$approved='C:\MuLab\approved\volume-'+$caseId;$config=[IO.File]::ReadAllText($approved+'-config.json')|ConvertFrom-Json;$failed=[IO.File]::ReadAllText($approved+'-recover-result.json')|ConvertFrom-Json;$original=[IO.File]::ReadAllText($approved+'-run-result.json')|ConvertFrom-Json;$id=[string]$original.nested.id
  if($caseId -notmatch '^[a-f0-9]{32}$' -or $config.caseId -ne $caseId -or $failed.caseId -ne $caseId -or $failed.complete -ne $false -or -not $failed.processExitConfirmed -or -not $failed.brokerExitConfirmed -or $failed.nested.id -ne $id -or $failed.nested.platformId -ne $original.nested.platformId -or (Get-LocalUser MuLabUser).SID.Value -ne $config.userSid){throw 'Exact terminal failed recovery required'}
  if(@(Get-CimInstance Win32_Process|Where-Object{($_.ExecutablePath -eq $config.node -and $_.CommandLine -like ('*'+$caseId+'*')) -or $_.ExecutablePath -like '*MuCodeSandbox-HyperVBroker-v1\bin\hv-*.exe' -or ($_.ExecutablePath -like 'C:\MuLab\volume-readers\*\python.exe' -and $_.CommandLine -like ('*'+$caseId+'*'))}).Count){throw 'An original controller, broker or reader remains live'}
  $root=Join-Path $env:ProgramData ('MuCodeSandbox-HyperVBroker-v1/users/'+$config.userSid);$ledgerFile=Join-Path $root 'vms.json';$ledger=[IO.File]::ReadAllText($ledgerFile)|ConvertFrom-Json;$disk=Join-Path $root ('vms/'+$id+'/disk.vhdx');$vm=Get-VM -Id ([guid]$original.nested.platformId);$drives=@(Get-VMHardDiskDrive -VM $vm);$vhd=Get-VHD $disk
  if($vm.Name -ne ('mu-win-'+$id.Replace('-','')) -or $vm.Notes -ne ('MuCodeSandbox Windows preview '+$vm.Name) -or [string]$vm.State -ne 'Off' -or $ledger.ownerSid -ne $config.userSid -or $ledger.records.$id.platformId -ne [string]$vm.Id -or $drives.Count -ne 1 -or [IO.Path]::GetFullPath($drives[0].Path) -ne $disk -or [long]$vhd.Size -ne 32GB -or $vhd.ParentPath -or @(Get-VMSnapshot -VM $vm).Count){throw 'Original stopped disk boundary changed'}
  $archive='C:\MuLab\private\volume-'+$caseId+'-failed-original';if((Test-Path -LiteralPath $archive) -ne $finish){throw 'Existing archive must be explicitly reviewed before finishing'}
  if($finish){foreach($name in @('ledger.json','ledger.backup.json')){if((Get-FileHash (Join-Path $archive $name)).Hash -ne (Get-FileHash $ledgerFile).Hash){throw 'Partial archive belongs to changed protected registration'}};if(Test-Path (Join-Path $archive 'receipt.json')){throw 'A completed archive is never rewritten'}}else{[IO.Directory]::CreateDirectory($archive)|Out-Null}
  $target=Join-Path $archive 'disk.vhdx';$pin=[IO.File]::Open($disk,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
  try{$before=(Get-FileHash $disk).Hash.ToLowerInvariant();if(-not $finish){$output=[IO.File]::Open($target,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$pin.CopyTo($output);$output.Flush($true)}finally{$output.Dispose()}};if((Get-FileHash $target).Hash.ToLowerInvariant() -ne $before -or (Get-FileHash $disk).Hash.ToLowerInvariant() -ne $before){throw 'Original archive byte verification failed'}}finally{$pin.Dispose()}
  foreach($pair in @(@($ledgerFile,'ledger.json'),@((Join-Path $root 'vms.backup.json'),'ledger.backup.json'),@(($approved+'-config.json'),'config.json'),@(($approved+'-run-result.json'),'run-result.json'),@(($approved+'-recover-result.json'),'failed-recover-result.json'),@(($approved+'-offline-result.json'),'offline-result.json'))){$to=Join-Path $archive $pair[1];if(Test-Path $to){if((Get-FileHash $to).Hash -ne (Get-FileHash $pair[0]).Hash){throw 'Existing archive sidecar differs'}}else{[IO.File]::Copy($pair[0],$to,$false)}}
  $app='C:\MuLab\public\volume-'+$caseId+'-app';foreach($name in @('credentials.dpapi','state.sqlite')){[IO.File]::Copy((Join-Path $app $name),(Join-Path $archive $name),$false)}
  $metadata='C:\MuLab\public\volume-'+$caseId+'-runtime\mu-win-'+$id.Replace('-','');$saved=Join-Path $archive 'management';[IO.Directory]::CreateDirectory($saved)|Out-Null;foreach($file in @(Get-ChildItem -LiteralPath $metadata -File)){if($file.Attributes -band [IO.FileAttributes]::ReparsePoint -or $file.Length -gt 16MB){throw 'Unexpected management artifact retained at source'};[IO.File]::Copy($file.FullName,(Join-Path $saved $file.Name),$false)}
  $receipt=@{complete=$true;caseId=$caseId;id=$id;platformId=([guid]$vm.Id).ToString('D');diskIdentifier=([guid]$vhd.DiskIdentifier).ToString('D');archive=$archive;originalDiskSha256=$before;originalUnchanged=$true;failedRecoveryPreserved=$true;offlineReaderWasReadOnly=$true;retirementAllowed=$true}
  [IO.File]::WriteAllText($approved+'-preserved.json',($receipt|ConvertTo-Json),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $archive 'receipt.json'),($receipt|ConvertTo-Json),[Text.UTF8Encoding]::new($false));return $receipt
 }
}
